module alu (
    input  wire             clk,
    input  wire             rst,
    input  wire [7:0]      a,
    input  wire [7:0]      b,
    input  wire [2:0]       opcode, // 000:ADD, 001:SUB, 010:AND, 011:OR, 100:XOR, 101:NOT, 110:SHL, 111:COMP
    output reg  [7:0]      alu_out,
    output reg              zero,
    output reg              carry
);

    reg [7:0] next_out;
    reg               next_carry;

    always @(*) begin
        case (opcode)
            3'b000: {next_carry, next_out} = a + b;
            3'b001: {next_carry, next_out} = a - b;
            3'b010: begin next_out = a & b; next_carry = 1'b0; end
            3'b011: begin next_out = a | b; next_carry = 1'b0; end
            3'b100: begin next_out = a ^ b; next_carry = 1'b0; end
            3'b101: begin next_out = ~a;    next_carry = 1'b0; end
            3'b110: begin next_out = a << 1; next_carry = a[7]; end
            3'b111: begin next_out = (a == b) ? 8'd1 : 8'd0; next_carry = (a < b); end
            default: begin next_out = 8'd0; next_carry = 1'b0; end
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            alu_out <= 8'd0;
            zero    <= 1'b0;
            carry   <= 1'b0;
        end else begin
            alu_out <= next_out;
            carry   <= next_carry;
            zero    <= (next_out == 8'd0);
        end
    end

endmodule
